insert into public.grapes (name, color, description, skin_color)
values ('Petite Sirah', 'RED', 'The name California uses for Durif, a French variety. DNA work at UC Davis (Meredith and others, 1999) found that 49 of 53 vines sold as Petite Sirah in California were Durif, and that Durif is most probably a seedling of Peloursin with Syrah as its other parent. It makes deeply coloured, tannic red wine, on its own or in blends.', 'blue-black');

-- united-states
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'Wine is made across the United States, but California alone makes about 81 per cent of it. This map covers the four states that matter most for fine wine: California, Washington, Oregon and New York. Wine regions here are American Viticultural Areas (AVAs): grape-growing areas the federal Alcohol and Tobacco Tax and Trade Bureau (TTB) defines by geography, with no rules on grapes, yields or winemaking.', 'Too varied for one description. The West Coast has dry summers: the cold Pacific and coastal fog cool California''s coastal valleys, and the Cascade Mountains leave eastern Washington and Oregon in a dry rain shadow. New York''s vineyards rely on deep lakes and the Atlantic to soften cold continental winters.', 'As varied as the climate: volcanic, marine sedimentary and wind-blown loess soils in Oregon''s Willamette Valley; loess over Ice Age flood gravels and basalt in Washington''s Columbia Valley; decomposed granite in California''s Sierra Foothills; shale and glacial deposits in New York''s Finger Lakes; sandy glacial soils on Long Island.', 'International varieties lead: Cabernet Sauvignon and Chardonnay in California and Washington, Pinot Noir in Oregon, Riesling in the Finger Lakes. Zinfandel has been grown in California since the Gold Rush.', 'Mostly dry reds and whites, usually labelled by grape variety rather than by place. Rosé, sparkling wine, sweet wines and a few fortified wines are made too.', array['TTB lists 280 established AVAs (August 2026); California has 154 of them', 'An AVA name on the label means at least 85% of the grapes come from that AVA (27 CFR 4.25)', 'A state or county name needs 75% of the wine from that place; a grape name needs 75% of that grape (27 CFR 4.23)', 'The first AVA was Augusta, Missouri, established on 20 June 1980', 'California makes about 81% of US wine (Wine Institute)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states';
