-- united-states.california
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'The largest wine state by far: about 81 per cent of the country''s wine, from roughly 540,000 acres of wine grapes. Its AVAs run the length of the state; this map groups them under the North Coast, Central Coast, Sierra Foothills and South Coast AVAs and the Central Valley. Napa Valley, designated in 1981, was California''s first AVA.', 'Mediterranean: mild, wet winters and long, dry summers. Near the coast, marine air and fog from the cold Pacific move inland through gaps and valleys in the Coast Ranges, so the coolest vineyards lie closest to the ocean and the warmest in the inland valleys and the foothills.', 'Every kind, changing over short distances: alluvial valley floors, volcanic soils in Napa and Lake County, calcareous soils in Paso Robles, decomposed granite in the Sierra Foothills and Temecula Valley, and deep sandy loam washed down from the Sierra Nevada around Lodi.', 'Cabernet Sauvignon and Chardonnay are the two most planted wine grapes. Pinot Noir comes from the cooler coast, Zinfandel from Lodi, Sonoma and the Sierra Foothills, and Petite Sirah (Durif) is widely grown for deep-coloured reds.', 'Mostly dry varietal reds and whites, from cool-coast Pinot Noir and Chardonnay to ripe Cabernet Sauvignon and Zinfandel. Sparkling wine and rosé are made too, and sweet and fortified wines in the Central Valley.', array['About 540,000 acres of wine grapes (CDFA estimate for 2025)', '154 of the 280 US AVAs lie wholly or partly in California (TTB)', 'Wine labelled California must be made only from California grapes, stricter than the federal 75% (17 CCR 17015)', 'At the 1976 Paris tasting, a 1973 Stag''s Leap Cabernet Sauvignon and a 1973 Chateau Montelena Chardonnay placed first', 'Napa Valley, designated in 1981, was California''s first AVA']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california';
