-- united-states.california.central-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'Central Valley is a grouping on this map, not an AVA. It gathers the eleven AVAs of the Sacramento and San Joaquin valleys that sit in no larger umbrella AVA: Lodi, Clarksburg, Madera, Capay Valley, Diablo Grande, Dunnigan Hills, Paulsell Valley, River Junction, Salado Creek, Tracy Hills and Winters Highlands. Lodi lies where the two valleys meet, and grapes came to it with the Gold Rush.', 'Hot, dry summers. Around Lodi and Clarksburg, breezes from San Francisco Bay come up through the Carquinez Strait and the Sacramento-San Joaquin Delta and cool the vineyards in the evening; further south, around Madera, the valley is warmer, which suits the sweet and fortified wines made there.', 'Around Lodi, deep, well-drained sandy loams of granite washed down from the Sierra Nevada by the Mokelumne River; elsewhere the valley floor is alluvial.', 'Zinfandel above all around Lodi, much of it from old bush vines, with Cabernet Sauvignon, Chardonnay and Petite Sirah. Clarksburg is known for Chenin Blanc, and Madera for Muscat.', 'Dry reds and whites, led by Lodi Zinfandel, plus sweet Muscat and port-style fortified wines from Madera.', array['A navigation grouping on this map, with eleven member AVAs; it has no legal status', 'Lodi has thousands of acres of old bush vines, most of them Zinfandel, many dry-farmed and own-rooted', 'Clarksburg, in the Sacramento River Delta, is known for Chenin Blanc', 'In Madera, Ficklin Vineyards has made port-style wine since 1948 and Quady Winery makes sweet Muscat']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.central-valley';
insert into public.wine_place_styles (wine_place_id, style, sort_order, editorial_status)
select id, 'RED', 0, 'PUBLISHED' from public.wine_places where canonical_key = 'united-states.california.central-valley';
