-- united-states.california.north-coast
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'The umbrella AVA for California''s northern coastal counties, established in 1983. It covers parts of Lake, Marin, Mendocino, Napa, Solano and Sonoma counties and contains, among many others, Napa Valley, Russian River Valley, Sonoma Coast and Anderson Valley. More than half of California''s wineries are in this region.', 'Mediterranean, and cooler toward the ocean. Marine air and fog come in from the Pacific and San Francisco Bay, so the Sonoma coast and the Carneros district by the bay are cool, while valleys and ridges further inland are warmer.', 'Varied over short distances: alluvial valley floors, volcanic soils on the ridges, and red volcanic soils around Mount Konocti, a dormant volcano, in Lake County.', 'Cabernet Sauvignon above all in Napa Valley; Chardonnay and Pinot Noir in the cooler districts near the coast and the bay; Zinfandel in Sonoma and Mendocino.', 'Dry reds and whites, from Napa Cabernet Sauvignon to coastal Pinot Noir and Chardonnay, and sparkling wine from the cooler districts.', array['Established 1983 (27 CFR 9.30)', 'Covers parts of Lake, Marin, Mendocino, Napa, Solano and Sonoma counties', 'Contains Napa Valley, California''s first AVA (1981), which grows about 4% of the state''s wine grapes', 'Home to more than half of California''s wineries (Discover California Wines)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.north-coast';
