-- united-states.california.sierra-foothills
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'A long AVA on the western slopes of the Sierra Nevada, established in 1987 across eight counties from Yuba in the north to Mariposa in the south. Vines came with the Gold Rush, and some of the oldest Zinfandel vineyards still in production are here. It contains El Dorado, Fair Play, California Shenandoah Valley, Fiddletown and North Yuba.', 'Warm, dry summers, tempered by height: nearly all its Zinfandel vineyards sit between about 1,200 and 3,500 feet, where nights are cooler than on the valley floor below.', 'Largely decomposed granite on the foothill slopes, well drained, with volcanic soils in parts of Amador and El Dorado counties.', 'Zinfandel, about 40 per cent of the vineyard acreage, much of it from old vines; Barbera, Syrah and Petite Sirah are the other main reds.', 'Mostly dry reds, above all Zinfandel, with some whites.', array['Established 1987 (27 CFR 9.120)', 'Eight counties: Yuba, Nevada, Placer, El Dorado, Amador, Calaveras, Tuolumne and Mariposa', 'Zinfandel is about 40% of the vineyard acreage (ZAP)', 'The Original Grandpere Vineyard, planted in 1869, is the oldest documented Zinfandel vineyard still producing']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.california.sierra-foothills';
