-- united-states.new-york
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'Most of New York''s vineyards grow native and hybrid grapes, above all Concord, for juice and jam: Concord makes up about 80 per cent of the state''s grape tonnage. Its fine wine comes from European vinifera grapes, planted with success only from the 1950s, chiefly in the Finger Lakes and on Long Island. The state has eleven AVAs, including Lake Erie and the Hudson River Region.', 'Continental, with cold winters once thought too harsh for European vines. The wine regions sit beside water: deep lakes store summer heat and delay spring frost in the Finger Lakes, and the Atlantic and Long Island Sound keep Long Island''s winters milder than the rest of the state.', 'Glacial in origin almost everywhere: grey shale and silty limestone bedrock under varied glacial soils in the Finger Lakes, and sandy, well-drained glacial moraine on Long Island.', 'Riesling leads the vinifera in the Finger Lakes, with Chardonnay, Cabernet Franc, Pinot Noir and Gewürztraminer; Merlot and Cabernet Franc lead on Long Island. Concord, Niagara and hybrids such as Seyval Blanc cover much of the rest of the state.', 'Dry to sweet Riesling and other aromatic whites, lighter-bodied reds, rosé and traditional-method sparkling wine.', array['Eleven AVAs lie wholly or partly in New York (TTB)', 'Concord is about 80% of New York''s grape tonnage, grown mostly for juice and jam (Cornell, 2018)', 'The Lake Erie region is the largest and oldest Concord-growing area in the world', 'Konstantin Frank planted vinifera on Keuka Lake from 1958 and released his first wines in 1962', 'Long Island''s first vineyard was planted in 1973']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.new-york';
