-- united-states.new-york.finger-lakes
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA in upstate New York, established in 1982, around a series of long, narrow glacial lakes, with Canandaigua, Keuka, Seneca and Cayuga at the heart of its wine growing. It has about 10,700 acres of vineyard and 144 wineries, and is known above all for Riesling. Seneca Lake and Cayuga Lake are AVAs within it.', 'Cool and continental. The lakes, some of the deepest in the United States, store heat from March to August and give it back for the rest of the year, which delays spring frost and stretches the growing season to about 195 days.', 'Devonian bedrock of grey shale and silty limestone, or of shale, siltstone, sandstone and limestone together, under glacial soils that change from site to site.', 'Riesling first, then Cabernet Franc, Pinot Noir, Gewürztraminer and Chardonnay; Lemberger (Blaufränkisch) is a local red. Native and hybrid grapes are still widely grown.', 'Riesling from dry to sweet, other aromatic whites, light reds, rosé and sparkling wine.', array['Established 1982 (27 CFR 9.34)', 'About 10,700 acres of vineyard and 144 wineries (NYWGF)', 'Contains the Cayuga Lake (1988) and Seneca Lake (2003) AVAs', 'Growing season about 195 days, lengthened by the lakes', 'Konstantin Frank''s vinifera plantings on Keuka Lake began in 1958']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.new-york.finger-lakes';
