-- united-states.new-york.long-island
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'The Long Island AVA, established in 2001, covers Nassau and Suffolk counties, and its vineyards lie at the eastern end, on the North Fork and the South Fork. Alex and Louisa Hargrave planted the first vineyard at Cutchogue in 1973; the island now has about 1,815 acres of vines. It contains the North Fork of Long Island and The Hamptons, Long Island AVAs, both older than it.', 'Maritime. The Atlantic, Long Island Sound and Peconic Bay moderate the temperature: long, warm summers, mild springs and autumns, winters much milder than upstate, and a growing season of about 225 days.', 'Glacial and sandy: deep, well-drained soils on the northern moraine, and coarser, fast-draining soils on the southern one.', 'Merlot and Cabernet Franc lead the reds, with Cabernet Sauvignon; Chardonnay and Sauvignon Blanc lead the whites.', 'Medium-bodied reds from Bordeaux varieties, crisp whites, rosé and sparkling wine.', array['Established 2001 (27 CFR 9.170); The Hamptons (1985) and North Fork (1986) AVAs came first', 'First vineyard planted in 1973, at Cutchogue on the North Fork', 'About 1,815 acres of vineyard and 82 wineries (NYWGF)', 'Growing season about 225 days']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.new-york.long-island';
