-- united-states.oregon
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'Oregon''s wine is shaped by one grape: Pinot Noir covers 60 per cent of the state''s 47,343 planted acres. The Willamette Valley, where David Lett planted the first Pinot Noir in 1965, holds the largest concentration of its wineries and vineyards; Southern Oregon, warmer and drier, grows a wider range. Oregon has 23 AVAs.', 'West of the Cascades, the Willamette Valley has cool, wet winters and warm, dry summers, and Southern Oregon is warmer and drier. In the north-east, the Columbia Valley and Walla Walla Valley AVAs cross the state line from Washington into dry country east of the mountains.', 'In the Willamette Valley, red volcanic Jory soils formed from Columbia River basalts, marine sedimentary soils such as Willakenzie, and wind-blown loess; in Southern Oregon, marine sediments, alluvial gravels and volcanic soils.', 'Pinot Noir is 60 per cent of the vineyard; Pinot Gris and Chardonnay follow in the Willamette Valley, and Southern Oregon adds Syrah, Cabernet Sauvignon, Merlot, Viognier and Tempranillo.', 'Mostly dry Pinot Noir, Pinot Gris and Chardonnay; rosé and sparkling wine are made from the same grapes.', array['47,343 planted acres in 2024, 60% of them Pinot Noir (Oregon Vineyard and Winery Census)', '23 AVAs; Mount Pisgah, Polk County, Oregon became the 23rd in 2022', 'A varietal wine must be at least 90% that grape, with 18 varieties allowed at 75% (Oregon rules)', 'An Oregon AVA or county name needs 95% of the grapes from it and 100% from Oregon', 'David Lett planted the Willamette Valley''s first Pinot Noir in 1965']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.oregon';
