-- united-states.oregon.southern-oregon
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An umbrella AVA established in 2004 over Oregon''s south-west, from south of Eugene to the California border. It joins the Umpqua Valley and Rogue Valley AVAs with Applegate Valley, Elkton Oregon and Red Hill Douglas County. Warmer and drier than the Willamette Valley, it grows a wider range of grapes on about 9,240 planted acres.', 'The warmest and driest part of western Oregon, broken into many microclimates by valleys and hillsides. The Umpqua Valley is warmer than the Willamette Valley but cooler than the Rogue Valley further south.', 'Marine sedimentary soils, alluvial gravels and volcanic soils, varying from valley to valley.', 'Pinot Noir and Pinot Gris, as elsewhere in Oregon, alongside grapes that need more warmth: Syrah, Cabernet Sauvignon, Merlot, Viognier and Tempranillo.', 'Dry reds and whites, from Pinot Noir to Syrah, Cabernet Sauvignon and Tempranillo, and rosé.', array['Established 2004 (27 CFR 9.179), in Douglas, Jackson and Josephine counties', 'About 2,283,600 acres in all, of which about 9,240 are planted (Oregon Wine Board)', 'Contains the Umpqua Valley, Rogue Valley, Applegate Valley, Elkton Oregon and Red Hill Douglas County AVAs', 'Abacela planted Tempranillo in the Umpqua Valley in 1995, the first varietal Tempranillo made in the Pacific Northwest']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.oregon.southern-oregon';
