-- united-states.washington
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'The second-largest wine-producing state, with about 35,000 acres of wine grapes and close to 1,000 wineries. Almost all of it lies east of the Cascade Mountains: over 99 per cent of the state''s vineyard acreage is in the Columbia Valley AVA. Washington has 22 AVAs; Columbia Valley, Columbia Gorge and Walla Walla Valley are shared with Oregon, and Lewis-Clark Valley with Idaho.', 'East of the Cascades the vineyards sit in a rain shadow, with 6 to 8 inches of rain a year in the Columbia Valley, and are irrigated from the Columbia River and its tributaries. Summer days bring up to 17 hours of sunlight, and days and nights differ by 30 to 40°F. West of the Cascades, Puget Sound is cool and wet.', 'Wind-blown loess and sand over gravel and slackwater sediment left by the Ice Age floods, with basalt beneath. Most vines grow on their own roots rather than grafted rootstock, since phylloxera survives poorly in very sandy soils.', 'Cabernet Sauvignon, Chardonnay, Merlot, Riesling and Syrah lead among more than 80 varieties grown, with Cabernet Franc and Sauvignon Blanc behind them.', 'Mostly dry reds and whites, the reds led by Cabernet Sauvignon, Merlot and Syrah; Riesling is made from dry to sweet, and some rosé.', array['The second-largest wine-producing state in the US (Washington State Wine Commission)', 'About 35,000 acres of wine grapes, 985 licensed wineries and 22 AVAs', 'Over 99% of the state''s vineyard acreage is in the Columbia Valley AVA', 'Cabernet Sauvignon was first planted in 1941, Riesling in 1961, Chardonnay in 1964 and Merlot in 1965 (WSWC)']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.washington';
