-- united-states.washington.columbia-valley
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'Washington''s inland AVA, established in 1984, covering more than 11 million acres of central and south-eastern Washington and a part of north-central Oregon. It holds over 99 per cent of Washington''s vineyard acreage and most of the state''s other AVAs, among them Yakima Valley, Red Mountain, Horse Heaven Hills and Walla Walla Valley.', 'Arid and semi-arid, in the rain shadow of the Cascades, with 6 to 8 inches of rain a year; the vineyards are irrigated from the Columbia River and its tributaries. Long summer days of sunlight and a wide gap between day and night temperatures.', 'Loess, wind-blown sand and silt, over gravel and slackwater sediment laid down by the Ice Age floods, with basalt beneath.', 'Cabernet Sauvignon, Chardonnay, Merlot, Riesling and Syrah lead.', 'Dry reds and whites above all, and Riesling in styles from dry to sweet.', array['Established 1984 (27 CFR 9.74); spans Washington and Oregon', 'More than 11 million acres in all (Washington State Wine Commission)', 'Over 99% of Washington''s vineyard acreage lies inside it', 'Contains Yakima Valley, Washington''s first AVA (1983), and Red Mountain (2001)']::text[], 'PUBLISHED'
