-- united-states.washington.puget-sound
insert into public.wine_place_articles (wine_place_id, description, climate, soils, grape_varieties, wine_styles, key_facts, editorial_status)
select id, 'An AVA west of the Cascades, established in 1995 in the lowlands around Puget Sound and its islands. It is large, about 5.5 million acres, but has only about 121 acres of vines, and it grows varieties seen nowhere else in the state, such as Madeleine Angevine and Siegerrebe.', 'Temperate and maritime: Washington''s coolest and wettest growing region, with 15 to 60 inches of rain a year, most of it between November and April.', 'Laid down by the ice sheet that shaped the Sound: glacial till, which gives sandy, rocky, well-drained soils, and outwash gravels and sands left by meltwater streams.', 'Pinot Noir and Riesling are the main grapes, with Müller-Thurgau, Madeleine Angevine, Siegerrebe and other early-ripening varieties.', 'Light, crisp whites and light reds, mostly Pinot Noir.', array['Established 1995 (27 CFR 9.151)', 'About 121 planted acres within 5.5 million acres (Washington State Wine Commission)', 'Washington''s coolest and wettest growing region', 'Grows Madeleine Angevine and Siegerrebe, seen nowhere else in the state']::text[], 'PUBLISHED'
  from public.wine_places where canonical_key = 'united-states.washington.puget-sound';
